import itertools

def is_sat(clauses, n):
    for assign in itertools.product([False, True], repeat=n):
        ok=True
        for clause in clauses:
            # clause is list of ints
            if not any((lit>0) == assign[abs(lit)-1] for lit in clause):
                ok=False
                break
        if ok:
            return True
    return False

n=3
