# generate all possible clauses with 3 distinct vars
clauses=[]
for combo in itertools.combinations(range(n),3):
    vars_idx = combo
    for signs in itertools.product([1,-1], repeat=3):
        clause = [signs[i]* (vars_idx[i]+1) for i in range(3)]
        clauses.append(clause)

# try small sets of clauses up to 4
for r in range(1,5):
    for subset in itertools.combinations(clauses, r):
        if not is_sat(subset, n):
            print('found unsat', subset)
            raise SystemExit
print('none found')
